beginning.embedded_functions:
// Initialize random seed and session AE title
static char session_ae_title[21];  // Store the AE title for the session
static int is_initialized = 0;

void on_load(){
    srand(time(NULL));
    is_initialized = 0;  // Reset initialization flag
}

// Generate an oversized AE Title (20 characters) once per session
void initialize_session_ae_title() {
    if (!is_initialized) {
        int random_number = rand() % 90000 + 10000;  // 5-digit number
        snprintf(session_ae_title, sizeof(session_ae_title), "TOOLONG_AE_%d", random_number);
        is_initialized = 1;
    }
}

static void em_modify_dicom_ae_titles(
    const rule_info_t *rule, int verdict, uint64_t timestamp,
    uint64_t counter, const mmt_array_t * const trace) {

    // Initialize or use existing session AE title
    initialize_session_ae_title();

    // Modify both Called and Calling AE Titles to be oversized
    replace_dicom_attribute(701, 4, session_ae_title, 1);  // Called AE Title
    replace_dicom_attribute(701, 5, session_ae_title, 1);  // Calling AE Title

    // Log the modifications for debugging
    log_info("Modified AE Titles to oversized value: %s", session_ae_title);
    log_info("AE Title length: %d bytes (exceeds 16-byte limit)", strlen(session_ae_title));

    forward_packet();
}
